function executeCard(context) {
  var ally = selectTarget({ type: 'piece', filter: 'ally' });
  if (ally.needsTargetSelection) return ally;
  context.piece = ally;
  var target = selectTarget({ type: 'piece', filter: 'enemy', range: 3 });
  if (target.needsTargetSelection) return target;
  var world = battle.extensions && battle.extensions.adventureWorld;
  var run = battle.extensions && battle.extensions.adventureCards;
  var ledger = run && run.players[playerId];
  if (!world || !world.activeZone || !ledger) return { success: false, message: '请在冒险战斗中使用' };
  var zone = world.activeZone;
  function inside(p) { return p.currentHp > 0 && p.x != null && p.y != null && p.x >= zone.x && p.x < zone.x + zone.width && p.y >= zone.y && p.y < zone.y + zone.height; }
  if (!inside(ally) || !inside(target) || Math.abs(ally.x - target.x) + Math.abs(ally.y - target.y) > 3) return { success: false, message: '请选择战区内的友方及其3格内敌人' };
  var cardId = context.card.id;
  var growth = ledger.growth[cardId] || 0;
  var result = dealDamage(ally, target, context.card.adventurePower.baseDamage, 'physical', battle, cardId);
  return { success: true, message: context.card.name + '造成' + result.damage + '点伤害' };
}
